# Store or restore the node_modules cache on Windows.
#
# Usage:
#   cache.ps1 archive   # create  .build/node_modules_cache/cache-<part>.7z (cache miss)
#   cache.ps1 extract   # restore .build/node_modules_cache/cache*.7z (cache hit)
#
# Splits node_modules into parts (see splitList.ts) that are archived and extracted in
# parallel: one 7-Zip process extracts them about twice as slowly as several. Extract
# also restores the single cache.7z of the caches saved before the parts. The archive
# and extract format must stay compatible; if you change the format here, bump
# build/.cachesalt to invalidate old caches.
param(
	[Parameter(Mandatory = $true)]
	[ValidateSet("archive", "extract")]
	[string]$Action
)

. build/azure-pipelines/win32/exec.ps1
$ErrorActionPreference = "Stop"

$parts = 8

# Runs 7-Zip in the current folder once for each of the given argument lists, in parallel.
# Fails when any of them fails.
function Invoke-SevenZipParallel([object[]]$Runs) {
	$folder = (Get-Location).Path
	$failed = $Runs | ForEach-Object -ThrottleLimit $parts -Parallel {
		Set-Location $using:folder
		$arguments = $_.Arguments
		& 7z.exe @arguments -bso0 -bsp0
		if ($LASTEXITCODE -ne 0) {
			"$($_.Name) (exit code $LASTEXITCODE)"
		}
	}
	if ($failed) {
		throw "7-Zip failed for $($failed -join ', ')"
	}
}

switch ($Action) {
	"archive" {
		Remove-Item .build/node_modules_list.txt.* -ErrorAction SilentlyContinue
		exec { node build/azure-pipelines/common/listNodeModules.ts .build/node_modules_list.txt }
		exec { node .github/workflows/node_modules_cache/splitList.ts .build/node_modules_list.txt $parts }
		exec { mkdir -Force .build/node_modules_cache }
		Remove-Item .build/node_modules_cache/cache*.7z -ErrorAction SilentlyContinue
		Invoke-SevenZipParallel (Get-ChildItem .build/node_modules_list.txt.* | ForEach-Object {
				[pscustomobject]@{ Name = $_.Name; Arguments = @('a', ".build/node_modules_cache/cache-$($_.Extension.TrimStart('.')).7z", '-mx3', "@$($_.FullName)") }
			})
	}
	"extract" {
		$archives = Get-ChildItem .build/node_modules_cache/cache*.7z
		if (-not $archives) {
			throw "No node_modules archive in .build/node_modules_cache"
		}
		Invoke-SevenZipParallel ($archives | ForEach-Object {
				[pscustomobject]@{ Name = $_.Name; Arguments = @('x', $_.FullName, '-aoa') }
			})
	}
}
